-- =====================================================
-- Week 4 - Day 2
-- PARTITION BY
-- Answers: Q11 - Q20
-- =====================================================

-- -----------------------------------------------------
-- Q11
-- Display every payment together with the
-- total revenue generated by that customer.
-- -----------------------------------------------------

SELECT
    payment_id,
    customer_id,
    amount,
    SUM(amount) OVER (
        PARTITION BY customer_id
    ) AS customer_total_revenue
FROM payment
ORDER BY
    customer_id,
    payment_id;


-- -----------------------------------------------------
-- Q12
-- Display every payment together with the
-- average payment amount made by that customer.
-- -----------------------------------------------------

SELECT
    payment_id,
    customer_id,
    amount,
    AVG(amount) OVER (
        PARTITION BY customer_id
    ) AS customer_average_payment
FROM payment
ORDER BY
    customer_id,
    payment_id;


-- -----------------------------------------------------
-- Q13
-- Display every payment together with the
-- total number of payments made by that customer.
-- -----------------------------------------------------

SELECT
    payment_id,
    customer_id,
    amount,
    COUNT(*) OVER (
        PARTITION BY customer_id
    ) AS customer_payment_count
FROM payment
ORDER BY
    customer_id,
    payment_id;


-- -----------------------------------------------------
-- Q14
-- Display every film together with the
-- average rental duration of films
-- having the same rating.
-- -----------------------------------------------------

SELECT
    film_id,
    title,
    rating,
    rental_duration,
    AVG(rental_duration) OVER (
        PARTITION BY rating
    ) AS average_rental_duration
FROM film
ORDER BY
    rating,
    film_id;


-- -----------------------------------------------------
-- Q15
-- Display every customer together with the
-- number of customers belonging to the same store.
-- -----------------------------------------------------

SELECT
    customer_id,
    first_name,
    last_name,
    store_id,
    COUNT(*) OVER (
        PARTITION BY store_id
    ) AS customers_in_store
FROM customer
ORDER BY
    store_id,
    customer_id;


-- -----------------------------------------------------
-- Q16
-- Display every rental together with the
-- total rentals made by that customer.
-- -----------------------------------------------------

SELECT
    rental_id,
    customer_id,
    rental_date,
    COUNT(*) OVER (
        PARTITION BY customer_id
    ) AS customer_total_rentals
FROM rental
ORDER BY
    customer_id,
    rental_date;


-- -----------------------------------------------------
-- Q17
-- Display every film together with the
-- average replacement cost
-- within its rating.
-- -----------------------------------------------------

SELECT
    film_id,
    title,
    rating,
    replacement_cost,
    AVG(replacement_cost) OVER (
        PARTITION BY rating
    ) AS average_replacement_cost
FROM film
ORDER BY
    rating,
    film_id;


-- -----------------------------------------------------
-- Q18
-- Explain the purpose of PARTITION BY.
-- -----------------------------------------------------

/*

PARTITION BY divides rows into
logical groups.

Each group is analyzed independently.

The original rows remain visible.

Examples

• Customer
• Store
• Film Rating
• Category

Calculations restart for
every partition.

*/


-- -----------------------------------------------------
-- Q19
-- Explain the difference between
-- GROUP BY and PARTITION BY.
-- -----------------------------------------------------

/*

GROUP BY

• Combines rows.
• Returns one row per group.
• Produces summary results.

---------------------------------------

PARTITION BY

• Keeps every original row.
• Creates analytical groups.
• Performs calculations
  within each partition.

---------------------------------------

GROUP BY

100 Rows

↓

10 Rows

---------------------------------------

PARTITION BY

100 Rows

↓

100 Rows

*/


